// Regenerates src/index.ts from the components folder (one export per Q<Name>.vue, QLink stays internal).
import { readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const src = join(dirname(fileURLToPath(import.meta.url)), '..', 'src');
const names = readdirSync(join(src, 'components')).filter((f) => /^Q\w+\.vue$/.test(f) && f !== 'QLink.vue').map((f) => f.slice(0, -4)).sort();
const lines = [
  '// Generated by scripts/gen-index.mjs — do not edit by hand.',
  "export const version = '1.1.0';",
  "export * from './locale';",
  "export { ICONS, ICON_NAMES, type IconName } from './icons';",
  "export { QLinkKey } from './link';",
  "export type { QDataTableColumn, QDataTableSort, QDataTableKey } from './maps/data';",
  ...names.map((n) => `export { default as ${n} } from './components/${n}.vue';`),
  '',
];
writeFileSync(join(src, 'index.ts'), lines.join('\n'));
console.log(`index.ts: ${names.length} components`);
